5070: function Get-PanelDefaultSize {
5071:     param([string]$Purpose = '')
5072:     if ($script:PanelSizes.ContainsKey($Purpose)) { return [int]$script:PanelSizes[$Purpose] }
5073:     return 1
5074: }
5075: 
5076: # Names given on the command line or in the roster as canonical slugs (D3, D8): every value split
5077: # at commas (powershell -File binds a [string[]] as ONE string), trimmed, lowercased, empty ones
5078: # dropped, duplicates removed (first one kept). { Items (string[]); Error ('' or the refusal) }.
5079: function ConvertTo-SlugList {
5080:     param([string[]]$Values, [string]$What = 'name')
5081:     $items = New-Object System.Collections.Generic.List[string]
5082:     foreach ($v in @($Values)) {
5083:         if ($null -eq $v) { continue }
5084:         foreach ($piece in ([string]$v).Split(',')) {
5085:             $s = $piece.Trim().ToLowerInvariant()
5086:             if (-not $s) { continue }
5087:             if ($s -notmatch $script:SlugPattern) {
5088:                 return [pscustomobject]@{ Items = [string[]]@(); Error = "$What '$($piece.Trim())' is not a slug (lowercase letters, digits, dot, dash, underscore; at most 41 characters, starting with a letter or digit)" }
5089:             }
5090:             if (-not $items.Contains($s)) { $items.Add($s) }
5091:         }
5092:     }
5093:     return [pscustomobject]@{ Items = [string[]]$items.ToArray(); Error = '' }
5094: }
