5096: # The lab a model id belongs to by the vendor table (D1), '' when its prefix is unknown.
5097: function Get-ModelLab {
5098:     param([string]$Model)
5099:     $m = ([string]$Model).Trim().ToLowerInvariant()
5100:     if (-not $m) { return '' }
5101:     foreach ($pair in $script:LabVendors) {
5102:         $kv = $pair.Split('=')
5103:         if ($m.StartsWith($kv[0])) { return $kv[1] }
5104:     }
5105:     return ''
5106: }
5107: 
5108: # The lab of a roster entry (D1): its `lab` (canonical lowercase), else the vendor table on the
5109: # model it resolves to, else a lab of its own - its lineage, lowercased (Source 'singleton'; a
5110: # routed panel warns). { Lab; Source ('roster' | 'vendor' | 'singleton') }.
5111: function Get-EntryLab {
5112:     param($Entry, [string]$Model = '', [string]$Lineage = '')
5113:     $declared = [string](Get-PropertyValue $Entry 'Lab' '')
5114:     if ($declared) { return [pscustomobject]@{ Lab = $declared; Source = 'roster' } }
5115:     $m = $Model
5116:     if (-not $m) { $m = [string](Get-PropertyValue $Entry 'Model' '') }
5117:     $v = Get-ModelLab $m
5118:     if ($v) { return [pscustomobject]@{ Lab = $v; Source = 'vendor' } }
5119:     $own = $Lineage
5120:     if (-not $own) { $own = Format-ReviewerLineage -Provider ([string]$Entry.Provider) -Model $m -Engine ([string](Get-PropertyValue $Entry 'Engine' '')) }
5121:     return [pscustomobject]@{ Lab = $own.ToLowerInvariant(); Source = 'singleton' }
5122: }
5123: 
5124: # A reviewer matcher (-Require, the roster's `require`; D7) against roster entries: `#<n>` (the
5125: # entry at roster position n), a bare provider label (every entry of it), or `<provider> ::
5126: # <model>` - either form with an optional ` [<engine>]` suffix. Compared field by field on what
5127: # the roster names (provider and model ordinal, the engine), never on a display string; a model-
5128: # less entry is named by its position or its label. { Positions (int[], roster order); Error }.
5129: function Resolve-ReviewerMatcher {
5130:     param([object[]]$Entries, [string]$Matcher)
5131:     $t = ([string]$Matcher).Trim()
5132:     $fail = { param($why) [pscustomobject]@{ Positions = [int[]]@(); Error = $why } }
5133:     if (-not $t) { return (& $fail 'an empty reviewer matcher') }
5134:     if ($t -match '^#(\d+)$') {
5135:         $pos = [int]$Matches[1]
5136:         $hit = @($Entries | Where-Object { [int]$_.Position -eq $pos })
5137:         if ($hit.Count -eq 0) { return (& $fail "'$t' names no roster position (the roster has $(@($Entries).Count) entries)") }
5138:         return [pscustomobject]@{ Positions = [int[]]@($pos); Error = '' }
5139:     }
5140:     $engine = ''
5141:     if ($t -match '^(.*\S)\s+\[([A-Za-z0-9_-]+)\]$') {
5142:         $t = $Matches[1]
5143:         $engine = $Matches[2].ToLowerInvariant()
5144:         if ($script:EngineNames -notcontains $engine) { return (& $fail "'$Matcher' names the engine '$engine' (known: $($script:EngineNames -join ', '))") }
5145:     }
5146:     $provider = $t
5147:     $model = $null
5148:     $sep = $t.IndexOf(' :: ')
5149:     if ($sep -ge 0) {
5150:         $provider = $t.Substring(0, $sep).Trim()
5151:         $model = $t.Substring($sep + 4).Trim()
5152:         if (-not $provider -or -not $model) { return (& $fail "'$Matcher' is not '<provider> :: <model>'") }
5153:     }
5154:     $hits = @($Entries | Where-Object {
5155:             $_.Provider -ceq $provider -and ($null -eq $model -or [string]$_.Model -ceq $model) -and (-not $engine -or [string]$_.Engine -eq $engine)
5156:         })
5157:     if ($hits.Count -eq 0) { return (& $fail "'$Matcher' matches no roster entry") }
5158:     return [pscustomobject]@{ Positions = [int[]]@($hits | ForEach-Object { [int]$_.Position }); Error = '' }
5159: }
5160: 
5161: # The required roster positions of a run (D7): -Require's matchers (explicit - `none` alone means
5162: # no requirement), else the roster's `require` for $Purpose (a -Panel run only: $UseRoster). {
5163: # Positions (int[], roster order, unique); Matchers (string[]); Source ('' | '-Require' | 'roster
5164: # require.<purpose>'); Error }.
5165: function Resolve-RequiredReviewers {
5166:     param($Roster, [string[]]$Require = @(), [string]$Purpose = '', [switch]$Explicit, [switch]$UseRoster)
5167:     $r = [pscustomobject]@{ Positions = [int[]]@(); Matchers = [string[]]@(); Source = ''; Error = '' }
5168:     $matchers = New-Object System.Collections.Generic.List[string]
5169:     if ($Explicit) {
5170:         foreach ($v in @($Require)) { foreach ($p in ([string]$v).Split(',')) { if ($p.Trim()) { $matchers.Add($p.Trim()) } } }
5171:         if ($matchers.Count -eq 1 -and $matchers[0] -ieq 'none') { $r.Source = '-Require none'; return $r }
5172:         if (@($matchers | Where-Object { $_ -ieq 'none' }).Count -gt 0) { $r.Error = "-Require none stands alone (it drops the roster's requirement); do not combine it with reviewers"; return $r }
5173:         $r.Source = '-Require'
5174:     } elseif ($UseRoster -and $Roster -and $Roster.PSObject.Properties['Require'] -and $null -ne $Roster.Require -and $Roster.Require.ContainsKey($Purpose)) {
5175:         foreach ($m in @($Roster.Require[$Purpose])) { $matchers.Add([string]$m) }
5176:         $r.Source = "roster require.$Purpose"
5177:     }
5178:     if ($matchers.Count -eq 0) { return $r }
5179:     if (-not $Roster -or -not $Roster.Exists) { $r.Error = '-Require names reviewers of the roster, and there is no reviewer roster'; return $r }
5180:     $set = New-Object System.Collections.Generic.List[int]
5181:     foreach ($m in $matchers) {
5182:         $res = Resolve-ReviewerMatcher -Entries @($Roster.Entries) -Matcher $m
5183:         if ($res.Error) { $r.Error = "$($r.Source): $($res.Error)"; return $r }
5184:         foreach ($p in $res.Positions) { if (-not $set.Contains([int]$p)) { $set.Add([int]$p) } }
5185:     }
5186:     $r.Positions = [int[]]@($set.ToArray() | Sort-Object)
5187:     $r.Matchers = [string[]]$matchers.ToArray()
5188:     return $r
5189: }
