5865: # The routing seed (D4): SHA-256 over the UTF-8 text `<task>|<purpose>|<brief sha256>|<the eligible
5866: # lineages, sorted ordinally, joined by ','>|<nonce>`. { Hex; Bytes; Text }.
5867: function Get-PanelSeed {
5868:     param([string]$Task, [string]$Purpose, [string]$BriefSha, [string[]]$Lineages, [string]$Nonce)
5869:     $sorted = [string[]]@($Lineages | ForEach-Object { [string]$_ })
5870:     [Array]::Sort($sorted, [StringComparer]::Ordinal)
5871:     $text = "$Task|$Purpose|$BriefSha|$($sorted -join ',')|$Nonce"
5872:     $sha = [System.Security.Cryptography.SHA256]::Create()
5873:     try { $bytes = $sha.ComputeHash($script:Utf8NoBom.GetBytes($text)) } finally { $sha.Dispose() }
5874:     return [pscustomobject]@{ Hex = (ConvertTo-HexString $bytes); Bytes = [byte[]]$bytes; Text = $text }
5875: }
