5811: function Get-RoutingRate {
5812:     param([double]$Yes, [double]$Partly, [double]$Count)
5813:     $p = $script:RoutingPrior
5814:     $w = ($Yes + 0.5 * $Partly + 2 * $p) / ($Count + 4 * $p)
5815:     return (0.25 + 1.75 * $w)
5816: }
