5818: # The routing score of one reviewer (D3) at the consult clock $UtcNow: { Score; Basis
5819: # ('purpose+topics' | 'purpose' | 'all-purpose' | 'neutral'); Ratings (the count behind the basis,
5820: # topic credit pooled - fractional); All (its ratings of every purpose in the window - the
5821: # evidence D5 asks for: >= 3); Yes; Partly; No (at the basis) }. -AllPurpose: the all-purpose rate
5822: # only (the scoreboard's lineage total).
5823: function Get-RoutingScore {
5824:     param([object[]]$Ratings, [string]$Provider, [string]$Model, [string]$Engine = 'codex', [string]$Purpose = '', [string[]]$Topics = @(), [datetime]$UtcNow = [datetime]::UtcNow, [switch]$AllPurpose)
5825:     if (-not $Engine) { $Engine = 'codex' }
5826:     $now = New-Object DateTimeOffset ([datetime]::SpecifyKind($UtcNow, [DateTimeKind]::Utc))
5827:     $from = $now.AddDays(-$script:RoutingWindowDays)
5828:     $mine = @($Ratings | Where-Object { $_ -and $_.Provider -ceq $Provider -and $_.Model -ceq $Model -and $_.Engine -eq $Engine -and $null -ne $_.ConsultWhen -and $_.ConsultWhen -ge $from })
5829:     $count = {
5830:         param([object[]]$List)
5831:         $c = @{ yes = 0.0; partly = 0.0; no = 0.0; n = 0.0 }
5832:         foreach ($x in $List) { $c[$x.Useful] += 1.0; $c.n += 1.0 }
5833:         $c
5834:     }
5835:     $all = & $count $mine
5836:     $res = [pscustomobject]@{ Score = $script:RoutingNeutral; Basis = 'neutral'; Ratings = 0.0; All = [int]$all.n; Yes = 0.0; Partly = 0.0; No = 0.0 }
5837:     $onPurpose = @($mine | Where-Object { $_.Purpose -ceq $Purpose })
5838:     if ($AllPurpose) { $onPurpose = @() }
5839:     $want = @($Topics | Where-Object { $_ })
5840:     if ($want.Count -gt 0) {
5841:         $c = @{ yes = 0.0; partly = 0.0; no = 0.0; n = 0.0 }
5842:         foreach ($x in $onPurpose) {
5843:             $t = @($x.Topics).Count
5844:             if ($t -eq 0) { continue }
5845:             foreach ($topic in $want) {
5846:                 if (@($x.Topics) -ccontains $topic) { $c[$x.Useful] += 1.0 / $t; $c.n += 1.0 / $t }
5847:             }
5848:         }
5849:         if ($c.n -ge $script:RoutingMinRatings - 1e-9) {
5850:             $res.Score = Get-RoutingRate -Yes $c.yes -Partly $c.partly -Count $c.n; $res.Basis = 'purpose+topics'; $res.Ratings = $c.n; $res.Yes = $c.yes; $res.Partly = $c.partly; $res.No = $c.no
5851:             return $res
5852:         }
5853:     }
5854:     $p = & $count $onPurpose
5855:     if ($p.n -ge $script:RoutingMinRatings) {
5856:         $res.Score = Get-RoutingRate -Yes $p.yes -Partly $p.partly -Count $p.n; $res.Basis = 'purpose'; $res.Ratings = $p.n; $res.Yes = $p.yes; $res.Partly = $p.partly; $res.No = $p.no
5857:         return $res
5858:     }
5859:     if ($all.n -ge $script:RoutingMinRatings) {
5860:         $res.Score = Get-RoutingRate -Yes $all.yes -Partly $all.partly -Count $all.n; $res.Basis = 'all-purpose'; $res.Ratings = $all.n; $res.Yes = $all.yes; $res.Partly = $all.partly; $res.No = $all.no
5861:     }
5862:     return $res
5863: }
