5989:         $m | Add-Member -NotePropertyName 'Lineage' -NotePropertyValue $lineage -Force
5990:         $m | Add-Member -NotePropertyName 'Lab' -NotePropertyValue ([string]$lab.Lab) -Force
5991:         $m | Add-Member -NotePropertyName 'LabSource' -NotePropertyValue ([string]$lab.Source) -Force
5992:         $m | Add-Member -NotePropertyName 'Score' -NotePropertyValue $score -Force
5993:         $m | Add-Member -NotePropertyName 'Required' -NotePropertyValue ([bool]$isReq) -Force
5994:         $m | Add-Member -NotePropertyName 'Rule' -NotePropertyValue '' -Force
5995:         $m | Add-Member -NotePropertyName 'Slot' -NotePropertyValue 0 -Force
5996:     }
5997:     $eligible = @($Members | Where-Object { $_ -and $_.State -eq 'run' })
5998:     $k = $Size
5999:     if ($k -le 0) { $k = $eligible.Count }
6000:     $pinned = @($eligible | Where-Object { $_.Required })
6001:     if ($k -lt $pinned.Count) { $k = $pinned.Count }
6002:     if ($k -gt $eligible.Count) { $k = $eligible.Count }
6003:     $mode = $Order
6004:     $fallback = ''
6005:     if ($mode -eq 'routed' -and @($eligible | Where-Object { $_.Score.All -ge $script:RoutingMinRatings }).Count -eq 0) { $mode = 'roster'; $fallback = 'no ratings' }
6006:     $seed = Get-PanelSeed -Task $Task -Purpose $Purpose -BriefSha $BriefSha -Lineages ([string[]]@($eligible | ForEach-Object { $_.Lineage })) -Nonce $Nonce
6007:     $seats = New-Object System.Collections.Generic.List[object]
6008:     if ($mode -eq 'routed') {
