6010:         foreach ($s in (Invoke-PanelDraw -Candidates $cands -K $k -Seed $seed.Bytes)) { $seats.Add([pscustomobject]@{ Slot = $s.Slot; Member = $s.Candidate.Member; Rule = $s.Rule }) }
6011:     } else {
