6018:     }
6019:     foreach ($s in $seats) { $s.Member.Rule = $s.Rule; $s.Member.Slot = $s.Slot }
6020:     foreach ($m in $eligible) {
6021:         if ($m.Slot -le 0) { $m.State = 'not-picked'; $m.Reason = "panel size $k" }
6022:     }
6023:     $warnings = New-Object System.Collections.Generic.List[string]
6024:     if ($mode -eq 'routed') {
