6028:     }
6029:     if ($SizeSource -ne '-PanelSize' -and $script:PanelFloorPurposes -contains $Purpose -and $seats.Count -lt 2) {
6030:         $warnings.Add("panel floor: a $Purpose panel runs $($seats.Count) member$(if ($seats.Count -ne 1) { 's' }) - $Purpose questions should hear at least 2 reviewers (pass -PanelSize to choose the size explicitly)")
6031:     }
6032:     $round = { param([double]$x, [int]$d) [Math]::Round($x, $d) }
6033:     $routing = [pscustomobject]@{
6034:         mode         = $mode
6035:         order        = $Order
6036:         fallback     = $fallback
6037:         seed         = $seed.Hex
