6039:         nonce_source = $NonceSource
6040:         size         = $k
6041:         size_source  = $SizeSource
6042:         eligible     = [object[]]@($eligible | ForEach-Object { [pscustomobject]@{ position = [int]$_.Entry.Position; lineage = $_.Lineage; lab = $_.Lab; lab_source = $_.LabSource; score = (& $round $_.Score.Score 4); basis = $_.Score.Basis; ratings = (& $round $_.Score.Ratings 2); required = [bool]$_.Required } })
6043:         picked       = [object[]]@($seats | ForEach-Object { [pscustomobject]@{ slot = $_.Slot; position = [int]$_.Member.Entry.Position; lineage = $_.Member.Lineage; lab = $_.Member.Lab; rule = $_.Rule } })
6044:         explored     = [object[]]@($seats | Where-Object { $_.Rule -like '*-explore' } | ForEach-Object { $_.Member.Lineage })
6045:         required     = [object[]]@($pinned | ForEach-Object { $_.Lineage })
6046:     }
6047:     return [pscustomobject]@{ Members = [object[]]@($Members); Picked = [object[]]@($seats | ForEach-Object { $_.Member }); K = $k; Routing = $routing; Warnings = [string[]]$warnings.ToArray() }
6048: }
