6106: # -Roles a,b,c over a panel's picked members (D8): the roles go by SCORE RANK (the routing score,
6107: # highest first; ties by seat), each role in the order given to the best-ranked member left that
6108: # is willing to take it (its roster entry's `roles`) when any member left is, else to the best-
6109: # ranked member left. More roles than members is refused. { Of (hashtable roster position ->
6110: # role); Error }.
6111: function Select-RoleAssignment {
6112:     param([object[]]$Members, [string[]]$Roles)
6113:     $r = [pscustomobject]@{ Of = @{}; Error = '' }
6114:     $list = @($Members | Where-Object { $_ })
6115:     if (@($Roles).Count -gt $list.Count) { $r.Error = "-Roles names $(@($Roles).Count) roles for $($list.Count) panel member$(if ($list.Count -ne 1) { 's' }) (at most one role each)"; return $r }
6116:     $ranked = New-Object System.Collections.Generic.List[object]
6117:     $i = 0
6118:     foreach ($m in $list) {
6119:         $i++
6120:         $sc = $script:RoutingNeutral
6121:         if ($m.PSObject.Properties['Score'] -and $null -ne $m.Score) { $sc = [double]$m.Score.Score }
6122:         $ranked.Add([pscustomobject]@{ Member = $m; Score = $sc; Seat = $i })
6123:     }
6124:     $left = New-Object System.Collections.Generic.List[object]
6125:     foreach ($x in @($ranked | Sort-Object -Property @{ Expression = { $_.Score }; Descending = $true }, @{ Expression = { $_.Seat }; Descending = $false })) { $left.Add($x) }
6126:     foreach ($role in @($Roles)) {
6127:         $willing = @($left | Where-Object { @(Get-PropertyValue $_.Member.Entry 'Roles' @()) -ccontains $role })
6128:         $take = $(if ($willing.Count -gt 0) { $willing[0] } else { $left[0] })
6129:         $r.Of[[int]$take.Member.Entry.Position] = $role
6130:         [void]$left.Remove($take)
6131:     }
6132:     return $r
6133: }
