6135: # The endpoint groups of a set of roster members ({ Entry; Identity } - Select-PanelMembers'
6136: # records): one group per provider label, merged with every other label whose members resolve
6137: # to the same provider fingerprint, to a fixed point (two labels on one base URL; every agy
6138: # label - they share one Google sign-in). A member whose identity is unresolved adds no
6139: # fingerprint. Groups are numbered in the order their first member appears. { Labels
6140: # (string[], first-seen order); Groups (object[] of { Labels (List[string]); Positions
6141: # (List[int] roster positions) }); GroupOf (hashtable roster position -> group index);
6142: # IndexOfLabel (hashtable label -> group index) }. Used twice (wave 24, D16): over a panel's
6143: # RUNNERS for the scheduling plan (Get-PanelPlan) and over ALL roster entries for the
6144: # availability view (Get-RosterAvailability: an outage marks its whole group).
6145: function Get-EndpointGroups {
6146:     param([object[]]$Members)
6147:     $labels = New-Object System.Collections.Generic.List[string]
6148:     $fps = New-Object System.Collections.Hashtable ([StringComparer]::Ordinal)
6149:     foreach ($m in @($Members | Where-Object { $_ })) {
6150:         $label = [string]$m.Entry.Provider
6151:         if (-not $fps.ContainsKey($label)) { $fps[$label] = New-Object System.Collections.Generic.List[string]; $labels.Add($label) }
6152:         $fp = ''
6153:         if ($m.Identity -and $m.Identity.Resolved) { $fp = [string]$m.Identity.Fingerprint }
6154:         if ($fp -and -not $fps[$label].Contains($fp)) { $fps[$label].Add($fp) }
6155:     }
6156:     # one group per label, then labels that share a fingerprint are merged (to a fixed point)
6157:     $groupOfLabel = New-Object System.Collections.Hashtable ([StringComparer]::Ordinal)
6158:     for ($i = 0; $i -lt $labels.Count; $i++) { $groupOfLabel[$labels[$i]] = $i }
6159:     $changed = $true
6160:     while ($changed) {
6161:         $changed = $false
6162:         for ($i = 0; $i -lt $labels.Count; $i++) {
6163:             for ($j = $i + 1; $j -lt $labels.Count; $j++) {
6164:                 $gi = $groupOfLabel[$labels[$i]]; $gj = $groupOfLabel[$labels[$j]]
6165:                 if ($gi -eq $gj) { continue }
6166:                 $shared = @($fps[$labels[$i]] | Where-Object { $fps[$labels[$j]].Contains($_) }).Count -gt 0
6167:                 if (-not $shared) { continue }
6168:                 $keep = [Math]::Min($gi, $gj); $drop = [Math]::Max($gi, $gj)
6169:                 foreach ($l in $labels) { if ($groupOfLabel[$l] -eq $drop) { $groupOfLabel[$l] = $keep } }
6170:                 $changed = $true
6171:             }
6172:         }
6173:     }
6174:     $groups = New-Object System.Collections.Generic.List[object]
6175:     $indexOf = @{}
6176:     $groupOf = @{}
6177:     foreach ($m in @($Members | Where-Object { $_ })) {
6178:         $label = [string]$m.Entry.Provider
6179:         $gid = $groupOfLabel[$label]
6180:         if (-not $indexOf.ContainsKey($gid)) {
6181:             $indexOf[$gid] = $groups.Count
6182:             $groups.Add([pscustomobject]@{ Labels = (New-Object System.Collections.Generic.List[string]); Positions = (New-Object System.Collections.Generic.List[int]) })
6183:         }
6184:         $g = $groups[$indexOf[$gid]]
6185:         if (-not $g.Labels.Contains($label)) { $g.Labels.Add($label) }
6186:         $g.Positions.Add([int]$m.Entry.Position)
6187:         $groupOf[[int]$m.Entry.Position] = $indexOf[$gid]
